    switch type {
    case 129:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return EngineMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 130:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return FitMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 131:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return PhaseMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 132:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return SourceKindMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 133:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return SubtitleEdgeMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 134:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return TrackKindMessage(rawValue: enumResultAsInt)
      }
      return nil
    case 135:
      return FrameSizeMessage.fromList(self.readValue() as! [Any?])
    case 136:
      return VideoDecoderMessage.fromList(self.readValue() as! [Any?])
    case 137:
      return CodecCapabilitiesMessage.fromList(self.readValue() as! [Any?])
    case 138:
      return SourceTracksMessage.fromList(self.readValue() as! [Any?])
    case 139:
      return ViewportMessage.fromList(self.readValue() as! [Any?])
    case 140:
      return OpenMessage.fromList(self.readValue() as! [Any?])
    case 141:
      return StateMessage.fromList(self.readValue() as! [Any?])
    case 142:
      return TimelineMessage.fromList(self.readValue() as! [Any?])
