private class PlayerPigeonCodecWriter: FlutterStandardWriter {
  override func writeValue(_ value: Any) {
    if let value = value as? EngineMessage {
      super.writeByte(129)
      super.writeValue(value.rawValue)
    } else if let value = value as? FitMessage {
      super.writeByte(130)
      super.writeValue(value.rawValue)
    } else if let value = value as? PhaseMessage {
      super.writeByte(131)
      super.writeValue(value.rawValue)
    } else if let value = value as? SourceKindMessage {
      super.writeByte(132)
      super.writeValue(value.rawValue)
    } else if let value = value as? SubtitleEdgeMessage {
      super.writeByte(133)
      super.writeValue(value.rawValue)
    } else if let value = value as? TrackKindMessage {
      super.writeByte(134)
      super.writeValue(value.rawValue)
    } else if let value = value as? FrameSizeMessage {
      super.writeByte(135)
      super.writeValue(value.toList())
    } else if let value = value as? VideoDecoderMessage {
      super.writeByte(136)
      super.writeValue(value.toList())
    } else if let value = value as? CodecCapabilitiesMessage {
      super.writeByte(137)
      super.writeValue(value.toList())
    } else if let value = value as? SourceTracksMessage {
      super.writeByte(138)
      super.writeValue(value.toList())
